INSERT INTO `wp_addonlibrary_addons` VALUES
(1,'Line Chart','line_chart_elementor','line_chart','elementor','Create customizable data visualizations with the Line Chart widget for Elementor. Add dynamic charts to your website to effectively display and track data trends with ease.',1,'{\"html\":\"<div id=\\\"{{uc_id}}\\\" class=\\\"ue_line_chart_wrapper\\\">\\n  <div id=\\\"{{uc_id}}_line\\\" class=\\\"ue_line_chart\\\"><\\/div>\\n<\\/div>\",\"html_item\":\"[\'{{item.title}}\',  {{item.y}}],\",\"html_item2\":\"{% if item_color_type == \\\"custom\\\" %}\\n  {% if line_color %}\\n    \'{{ line_color }}\',\\n  {% else %}\\n    \'#374b66\',\\n  {% endif %}\\n{% endif %}\",\"css\":\"#{{uc_id}}{\\n  position: relative;\\n  display:flex;\\n  flex-direction:row;\\n}\\n#{{uc_id}} .ue_line_chart{\\n  position:relative;\\n  max-width:100%;\\n  width:{{width}};\\n  height:{{height}};\\n}\\n@media (max-width: 1024px){\\n  #{{uc_id}} .ue_line_chart{\\n    width:{{width_tablet}};\\n    height:{{height_tablet}};\\n  }\\n}\\n@media (max-width: 767px){\\n  #{{uc_id}} .ue_line_chart{\\n    width:{{width_mobile}};\\n    height:{{height_mobile}};\\n  }\\n}\",\"js\":\"jQuery(document).ready(function(){\\n  \\n  function getResponsiveChartArea() {\\n    const width = window.innerWidth;\\n    if (width <= 767) return \\\"{% if chart_area_mobile_nounit %}{{chart_area_mobile_nounit}}{% else %}{{chart_area_nounit}}{% endif %}%\\\";\\n    else if (width <= 1023) return \\\"{% if chart_area_tablet_nounit %}{{chart_area_tablet_nounit}}{% else %}{{chart_area_nounit}}{% endif %}%\\\";\\n    else return \\\"{{chart_area_nounit}}%\\\";\\n  }\\n\\n  function drawChart_{{uc_id}}() {\\n    var data = google.visualization.arrayToDataTable([\\n      [\'{{x_title}}\', \'{{y_title}}\'],\\n      {{put_items()}}\\n    ]);\\n\\n    var options = {      \\n      {% if show_title == \\\"true\\\" %}\\n        title: \'{{title}}\',\\n        titleTextStyle: {\\n          {% if font_family %}fontName: \'{{font_family|raw}}\',{% endif %}\\n          {% if font_size %}fontSize: {{font_size_nounit}},{% endif %}\\n          {% if title_color %}color: \'{{title_color}}\',{% endif %}\\n          bold: {{title_bold}},\\n        },\\n      {% endif %}\\n        {% if text_font_family %}fontName: \'{{text_font_family|raw}}\',{% endif %}\\n        {% if text_font_size %}fontSize: {{text_font_size_nounit}},{% endif %}\\n        width: \'100%\',\\n        height: \'100%\',\\n        backgroundColor: \'transparent\',\\n        hAxis: {\\n          {% if minimum_range_x %}minValue: {{minimum_range_x}},{% endif %}\\n          {% if maximum_value_x %}maxValue: {{maximum_value_x}},{% endif %}\\n          title: \'{{x_axis_label|raw}}\', \\/\\/ Horizontal axis title\\n          gridlines: { {% if gridlines_x %}count: {{gridlines_x}},{% endif %} {% if gridlines_color_x %}color: \'{{gridlines_color_x}}\'{% endif %} },\\n          format: \'{{value_format_x}}\',\\n          textStyle: {\\n            {% if text_color_x %}color: \'{{text_color_x}}\',{% endif %}\\n          },\\n          titleTextStyle: {\\n            {% if axis_title_color_x %}color: \'{{axis_title_color_x}}\',{% endif %}\\n            {% if axis_title_font_size_x %}fontSize: {{axis_title_font_size_x}},{% endif %}\\n            {% if axis_title_bold_x %}bold: {{axis_title_bold_x}},{% endif %}\\n          }\\n        },\\n        vAxis: {\\n          {% if minimum_range %}minValue: {{minimum_range}},{% endif %}\\n          {% if maximum_value %}maxValue: {{maximum_value}},{% endif %}\\n          title: \'{{y_axis_label|raw}}\', \\/\\/ Vertical axis title\\n          gridlines: { {% if gridlines %}count: {{gridlines}},{% endif %} {% if gridlines_color %}color: \'{{gridlines_color}}\'{% endif %} },\\n          format: \'{{value_format}}\',\\n          textStyle: {\\n            {% if text_color_y %}color: \'{{text_color_y}}\',{% endif %}\\n          },\\n          titleTextStyle: {\\n            {% if axis_title_color_y %}color: \'{{axis_title_color_y}}\',{% endif %}\\n            {% if axis_title_font_size_y %}fontSize: {{axis_title_font_size_y}},{% endif %}\\n            {% if axis_title_bold_y %}bold: {{axis_title_bold_y}},{% endif %}\\n          }\\n        },\\n        curveType: \'{{curve_type}}\',\\n        {% if line_width_nounit %}lineWidth: {{line_width_nounit}},{% endif %}\\n        {% if data_point_size_nounit %}pointSize: {{data_point_size_nounit}},{% endif %}\\n        pointShape: \'{{data_point_shape}}\',\\n        {% if show_legend != \\\"none\\\" %}\\n        legend: { \\n          position: \'{{show_legend}}\',\\n          alignment: \'{{legend_alignment}}\',\\n          textStyle: {\\n            {% if legend_font_family %}fontName: \'{{legend_font_family|raw}}\',{% endif %}\\n            {% if legend_color %}color: \'{{legend_color}}\',{% endif %}\\n            {% if legend_font_size %}fontSize: {{legend_font_size}},{% endif %}\\n            bold: {{legend_bold}},\\n          }\\n        },\\n        {% else %}\\n            legend:\'none\',\\n        {% endif %}\\n        tooltip: {\\n             trigger: \'focus\', \\n             textStyle: {\\n                 {% if tt_font_family %}fontName: \'{{tt_font_family|raw}}\',{% endif %}\\n                 {% if tt_font_size_nounit %}fontSize: {{tt_font_size_nounit}},{% endif %}\\n                 {% if tt_text_color %}color: \'{{tt_text_color}}\',{% endif %}\\n                 bold: {{tt_bold}}\\n             }, \\n             showColorCode: {{show_tt_color}}\\n        },\\n        chartArea: { width: getResponsiveChartArea(), height: getResponsiveChartArea() },\\n        {% if item_color_type == \\\"custom\\\" %} colors: [{{put_items2()}}] {% endif %}\\n    };\\n    var chart = new google.visualization.LineChart(document.getElementById(\'{{uc_id}}_line\'));\\n\\n    chart.draw(data, options);\\n  }\\n\\n  google.charts.load(\'current\', {\'packages\':[\'corechart\']});\\n  google.charts.setOnLoadCallback(drawChart_{{uc_id}});\\n                  \\n  function debounce(func, wait) {\\n    let timeout;\\n    return function(...args) {\\n        const context = this;\\n        clearTimeout(timeout);\\n        timeout = setTimeout(() => func.apply(context, args), wait);\\n    };\\n  }\\n                  \\n  window.addEventListener(\'resize\', debounce(drawChart_{{uc_id}}, 200));\\n  \\n});\"}','{\"options\":{\"enable_items\":1,\"items_section_title\":\"\",\"items_section_heading\":\"\",\"items_title_field\":\"\",\"path_assets\":\"uc_curve_chart_two\",\"js_as_module\":false,\"addon_icon\":\"fas fa-line-chart\",\"dynamic_addon\":\"false\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"Create customizable data visualizations with the Line Chart widget for Elementor. Add dynamic charts to your website to effectively display and track data trends with ease.\",\"link_resource\":\"\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/line-chart-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size\":\"full\",\"preview_custom_width\":\"\",\"preview_bgcol\":\"#ffffff\",\"special\":\"\",\"special_data\":\"\",\"is_free_addon\":true,\"is_new_addon\":false,\"is_trending\":false},\"params\":[{\"type\":\"uc_radioboolean\",\"title\":\"Show Title\",\"name\":\"show_title\",\"description\":\"\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":[],\"condition_attribute2\":\"\",\"condition_operator2\":\"equal\",\"condition_value2\":null,\"label_block\":false,\"tabname\":\"\",\"default_value\":\"true\",\"true_name\":\"Yes\",\"true_value\":\"true\",\"false_name\":\"No\",\"false_value\":\"false\",\"is_pro\":true,\"is_responsive\":false,\"default_value_tablet\":\"\",\"default_value_mobile\":\"\",\"__attr_catid__\":\"cat_general_general\"},{\"type\":\"uc_textfield\",\"title\":\"Title\",\"name\":\"title\",\"description\":\"\",\"enable_condition\":true,\"condition_attribute\":\"show_title\",\"condition_operator\":\"