(16214,'sby_notifications','a:4:{s:6:\"update\";i:1769906984;s:4:\"feed\";a:1:{i:0;a:9:{s:2:\"id\";i:45;s:6:\"plugin\";a:6:{i:0;s:9:\"instagram\";i:1;s:8:\"facebook\";i:2;s:7:\"twitter\";i:3;s:7:\"reviews\";i:4;s:6:\"tiktok\";i:5;s:7:\"youtube\";}s:4:\"type\";a:1:{i:0;s:4:\"free\";}s:5:\"title\";s:48:\"Add a Free WhatsApp Chat to Your Site in Minutes\";s:7:\"content\";s:541:\"Hey there! We\'re excited to share something new from the Smash Balloon team. Knowing how important direct connection is, we built WPChat. It’s the easiest way to chat with your site visitors on WhatsApp, Messenger, and Telegram, helping you provide instant, personal support. It\'s completely free to get started. The free version includes live chat for one agent via WhatsApp, Facebook Messenger or Telegram, AI-Powered Smart FAQs to automatically answer questions, and a beautiful, customizable chat widget that looks great on any device.\";s:5:\"start\";s:19:\"2025-10-30 00:00:00\";s:3:\"end\";s:19:\"2026-10-30 23:59:59\";s:5:\"image\";s:7:\"balloon\";s:4:\"btns\";a:2:{s:7:\"primary\";a:3:{s:4:\"text\";s:19:\"Try WPChat for Free\";s:3:\"url\";s:181:\"https://wpchat.com/how-to-get-free-whatsapp-chat-plugin-wordpress/?utm_source={plugin}-free&utm_medium=plugin-dashboard-notices&utm_campaign=wpchatlaunch&utm_content=try-wpchat-free\";s:4:\"attr\";a:1:{i:0;s:11:\"targetblank\";}}s:9:\"secondary\";a:3:{s:4:\"text\";s:17:\"Add Free Chat Now\";s:3:\"url\";s:179:\"https://wpchat.com/how-to-get-free-whatsapp-chat-plugin-wordpress/?utm_source={plugin}-free&utm_medium=plugin-dashboard-notices&utm_campaign=wpchatlaunch&utm_content=add-free-chat\";s:4:\"attr\";a:1:{i:0;s:11:\"targetblank\";}}}}}s:6:\"events\";a:0:{}s:9:\"dismissed\";a:0:{}}','auto'),
(16215,'sby_newuser_notifications','a:4:{s:6:\"update\";i:1762909411;s:4:\"feed\";a:2:{s:6:\"review\";a:6:{s:5:\"title\";s:25:\"How Do You Like {plugin}?\";s:7:\"content\";s:260:\"It\'s great to see that you\'ve been using the <strong>{plugin}</strong> plugin for a while now. Hopefully you\'re happy with it!&nbsp; If so, would you consider leaving a positive review? It really helps to support the plugin and helps others to discover it too!\";s:2:\"id\";s:6:\"review\";s:5:\"image\";s:12:\"sbi-icon.png\";s:4:\"btns\";a:4:{s:7:\"primary\";a:4:{s:3:\"url\";s:12:\"{review-url}\";s:4:\"attr\";a:1:{i:0;s:11:\"targetblank\";}s:5:\"class\";s:18:\"sbi_notice_dismiss\";s:4:\"text\";s:18:\"Sure, I\'d love to!\";}s:7:\"dismiss\";a:3:{s:3:\"url\";a:1:{s:28:\"sbi_ignore_rating_notice_nag\";s:1:\"1\";}s:5:\"class\";s:18:\"sbi_notice_dismiss\";s:4:\"text\";s:9:\"No thanks\";}s:8:\"complete\";a:3:{s:3:\"url\";a:1:{s:28:\"sbi_ignore_rating_notice_nag\";s:1:\"1\";}s:5:\"class\";s:18:\"sbi_notice_dismiss\";s:4:\"text\";s:27:\"I\'ve already given a review\";}s:5:\"later\";a:3:{s:3:\"url\";a:1:{s:28:\"sbi_ignore_rating_notice_nag\";s:5:\"later\";}s:5:\"class\";s:18:\"sbi_notice_dismiss\";s:4:\"text\";s:12:\"Ask Me Later\";}}s:4:\"wait\";s:2:\"14\";}s:8:\"discount\";a:8:{s:5:\"title\";s:28:\"Attention {platform} Lovers!\";s:7:\"content\";s:195:\"<strong>Exclusive offer!</strong> We don\'t run promotions very often, but for a limited time we\'re offering <strong>{amount} off</strong> our Pro version to all users of our free {plugin} plugin.\";s:2:\"id\";s:8:\"discount\";s:6:\"amount\";s:3:\"60%\";s:5:\"image\";s:12:\"sbi-icon.png\";s:13:\"image_overlay\";s:7:\"60% off\";s:4:\"btns\";a:2:{s:7:\"primary\";a:4:{s:3:\"url\";s:127:\"https://smashballoon.com/{slug}/?utm_campaign={campaign}&utm_source=notices&utm_medium=newuser&discount={lowerplatform}thankyou\";s:5:\"class\";s:32:\"sbi_notice_dismiss sbi_offer_btn\";s:4:\"text\";s:14:\"Get this offer\";s:4:\"attr\";a:1:{i:0;s:11:\"targetblank\";}