alue\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridColumnTablet\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridColumnMobile\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridRowDesktop\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridRowTablet\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridRowMobile\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridAlignItemsDesktop\":\"stretch\",\"gridAlignItemsTablet\":\"stretch\",\"gridAlignItemsMobile\":\"stretch\",\"gridJustifyItemsDesktop\":\"stretch\",\"gridJustifyItemsTablet\":\"stretch\",\"gridJustifyItemsMobile\":\"stretch\",\"gridAlignContentDesktop\":\"stretch\",\"gridAlignContentTablet\":\"stretch\",\"gridAlignContentMobile\":\"stretch\",\"gridJustifyContentDesktop\":\"stretch\",\"gridJustifyContentTablet\":\"stretch\",\"gridJustifyContentMobile\":\"stretch\",\"orderDesktop\":\"initial\",\"orderTablet\":\"initial\",\"orderMobile\":\"initial\",\"customOrderDesktop\":\"\",\"customOrderTablet\":\"\",\"customOrderMobile\":\"\",\"containerBorderTopWidth\":\"\",\"containerBorderLeftWidth\":\"\",\"containerBorderRightWidth\":\"\",\"containerBorderBottomWidth\":\"\",\"containerBorderTopLeftRadius\":\"\",\"containerBorderTopRightRadius\":\"\",\"containerBorderBottomLeftRadius\":\"\",\"containerBorderBottomRightRadius\":\"\",\"containerBorderRadiusUnit\":\"px\",\"containerBorderTopWidthTablet\":\"\",\"containerBorderLeftWidthTablet\":\"\",\"containerBorderRightWidthTablet