(268,1,'2025-11-01 09:58:21','2025-11-01 09:58:21','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"spectra-one\",\"tagName\":\"header\",\"SWTTransparentHeader\":true} /-->\n\n<!-- wp:group {\"metadata\":{\"name\":\"DesktopHero\"},\"align\":\"wide\",\"style\":{\"color\":{\"gradient\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dgradient\\u002d\\u002dprimary)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-background\" style=\"background:var(--wp--preset--gradient--primary);margin-top:var(--wp--preset--spacing--xx-large);margin-bottom:0;padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:0\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0;flex-basis:80%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"className\":\"wp-block-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}},\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\" style=\"letter-spacing:-1px\"><mark style=\"background-color:rgba(0, 0, 0, 0);color:#248eaf\" class=\"has-inline-color\">We Fetch the Clients </mark><mark style=\"background-color:rgba(0, 0, 0, 0);color:#1e2a38\" class=\"has-inline-color\">You Handle the Pets</mark></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image-desktop\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"desktop-kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image-desktop\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"desktop-fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"color\":{\"gradient\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dgradient\\u002d\\u002dprimary)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\"},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-group alignwide has-background\" style=\"background:var(--wp--preset--gradient--primary);margin-top:var(--wp--preset--spacing--xx-large);margin-bottom:0;padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:0\"><!-- wp:spacer {\"SWTHideDesktop\":true} -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0;flex-basis:80%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"className\":\"wp-block-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}},\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\" style=\"letter-spacing:-1px\"><mark style=\"background-color:rgba(0, 0, 0, 0);color:#248eaf\" class=\"has-inline-color\">We Fetch the Clients </mark><mark style=\"background-color:rgba(0, 0, 0, 0);color:#1e2a38\" class=\"has-inline-color\">You Handle the Pets</mark></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image\",\"SWTHideDesktop\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideDesktop\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"var:preset|spacing|xx-large\"},\"blockGap\":\"var:preset|spacing|x-large\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-tertiary-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:var(--wp--preset--spacing--xx-large)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"wp-block-heading\",\"textColor\":\"heading\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-heading-color has-text-color\">Discover a new way to build website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Get online quickly with easy-to-use Full Site Editor builder</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":1039,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"8px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"https://happytailspawcare.com/wp-content/themes/spectra-one/assets/image/content-1.png\" alt=\"\" class=\"wp-image-1039\" style=\"border-radius:8px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|medium\",\"right\":\"var:preset|spacing|x-small\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--x-small);padding-left:var(--wp--preset--spacing--medium)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"letterSpacing\":\"2px\"}},\"fontSize\":\"x-small\"} -->\n<p class=\"has-x-small-font-size\" style=\"letter-spacing:2px\">01</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"wp-block-heading\",\"textColor\":\"heading\"} -->\n<h4 class=\"wp-block-heading has-heading-color has-text-color\">Visual editing experience</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Customize the entire website layout, including the header, footer, and all other template parts. With FSE, we can create and edit templates for their entire website, including single posts, archive pages, and custom post types.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|small\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-link-color has-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--small);font-style:normal;font-weight:500\"><a href=\"#\">Learn More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|x-small\",\"left\":\"var:preset|spacing|medium\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--x-small);padding-left:var(--wp--preset--spacing--medium)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"letterSpacing\":\"2px\"}},\"fontSize\":\"x-small\"} -->\n<p class=\"has-x-small-font-size\" style=\"letter-spacing:2px\">02</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"wp-block-heading\",\"textColor\":\"heading\"} -->\n<h4 class=\"wp-block-heading has-heading-color has-text-color\">Innovative block patterns</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Block patterns are pre-designed block layouts that we can easily insert into their content. These patterns can help to save time and create visually appealing designs. Allows us to create custom themes using the block-based template.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|small\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-link-color has-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--small);font-style:normal;font-weight:500\"><a href=\"#\">Learn More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":1040,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"8px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"https://happytailspawcare.com/wp-content/themes/spectra-one/assets/image/content-2.png\" alt=\"\" class=\"wp-image-1040\" style=\"border-radius:8px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":1041,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"8px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"https://happytailspawcare.com/wp-content/themes/spectra-one/assets/image/content-3.png\" alt=\"\" class=\"wp-image-1041\" style=\"border-radius:8px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|medium\",\"right\":\"var:preset|spacing|x-small\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--x-small);padding-left:var(--wp--preset--spacing--medium)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"letterSpacing\":\"2px\"}},\"fontSize\":\"x-small\"} -->\n<p class=\"has-x-small-font-size\" style=\"letter-spacing:2px\">03</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"wp-block-heading\",\"textColor\":\"heading\"} -->\n<h4 class=\"wp-block-heading has-heading-color has-text-color\">Beautiful global styles</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Global styles enable us to create and apply consistent design elements across the entire website, including typography, colors, and spacing. Providing us with more control over our website\'s look and feel.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|small\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-link-color has-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--small);font-style:normal;font-weight:500\"><a href=\"#\">Learn More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|x-large\",\"bottom\":\"var:preset|spacing|x-large\"},\"blockGap\":\"var:preset|spacing|medium\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--x-large);padding-bottom:var(--wp--preset--spacing--x-large)\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|x-small\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-bottom:var(--wp--preset--spacing--x-small)\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"2px\",\"textTransform\":\"uppercase\"}},\"textColor\":\"primary\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-text-align-center has-primary-color has-text-color has-x-small-font-size\" style=\"letter-spacing:2px;text-transform:uppercase\">Testimonials</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">See what people have to say about us</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|medium\",\"left\":\"var:preset|spacin