(375,1,'2025-12-30 01:01:04','2025-12-30 01:01:04','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"spectra-one\",\"tagName\":\"header\",\"SWTTransparentHeader\":true} /-->\n\n<!-- wp:group {\"metadata\":{\"name\":\"DesktopHero\"},\"align\":\"wide\",\"style\":{\"color\":{\"gradient\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dgradient\\u002d\\u002dprimary)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\"},\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div class=\"wp-block-group alignwide has-background\" style=\"background:var(--wp--preset--gradient--primary);margin-top:var(--wp--preset--spacing--xx-large);margin-bottom:0;padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:0\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0;flex-basis:80%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"className\":\"wp-block-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}},\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\" style=\"letter-spacing:-1px\"><mark style=\"background-color:rgba(0, 0, 0, 0);color:#248eaf\" class=\"has-inline-color\">We Fetch the Clients </mark><mark style=\"background-color:rgba(0, 0, 0, 0);color:#1e2a38\" class=\"has-inline-color\">You Handle the Pets</mark></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image-desktop\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"desktop-kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image-desktop\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"desktop-fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"color\":{\"gradient\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dgradient\\u002d\\u002dprimary)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\"},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-group alignwide has-background\" style=\"background:var(--wp--preset--gradient--primary);margin-top:var(--wp--preset--spacing--xx-large);margin-bottom:0;padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:0\"><!-- wp:spacer {\"SWTHideDesktop\":true} -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0;flex-basis:80%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"className\":\"wp-block-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}},\"textColor\":\"white\",\"SWTHideDesktop\":true} -->\n<h1 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\" style=\"letter-spacing:-1px\"><mark style=\"background-color:rgba(0, 0, 0, 0);color:#248eaf\" class=\"has-inline-color\">We Fetch the Clients </mark><mark style=\"background-color:rgba(0, 0, 0, 0);color:#1e2a38\" class=\"has-inline-color\">You Handle the Pets</mark></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image fixed\",\"SWTHideDesktop\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image fixed\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideDesktop\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"var:preset|spacing|xx-large\"},\"blockGap\":\"var:preset|spacing|x-large\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-tertiary-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:var(--wp--preset--spacing--xx-large)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:uagb/image {\"block_id\":\"725c75ec\",\"url\":\"https://happytailspawcare.com/wp-content/uploads/2025/10/dogs_conference_room_laptop_mobile_2.png\",\"urlTablet\":\"https://happytailspawcare.com/wp-content/uploads/2025/10/dogs_conference_room_laptop_mobile_2.png\",\"urlMobile\":\"https://happytailspawcare.com/wp-co