n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image-desktop\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"desktop-kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image-desktop\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideTab\":true,\"SWTHideMob\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"desktop-fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"color\":{\"gradient\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dgradient\\u002d\\u002dprimary)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"0\"}},\"position\":{\"type\":\"\"}},\"layout\":{\"type\":\"constrained\"},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-group alignwide has-background\" style=\"background:var(--wp--preset--gradient--primary);margin-top:var(--wp--preset--spacing--xx-large);margin-bottom:0;padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:0\"><!-- wp:spacer {\"SWTHideDesktop\":true} -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0;flex-basis:80%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"className\":\"wp-block-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}},\"textColor\":\"white\",\"SWTHideDesktop\":true} -->\n<h