=\';\nvar query = new google.visualization.Query(dataSourceUrl);\nquery.send(handleQueryResponse);\n}\nfunction handleQueryResponse(response) {\n      if (response.isError()) {\n        alert(\'Error in query: \' + response.getMessage() + \' \' + response.getDetailedMessage());\n        return;\n      }\n      var data = response.getDataTable();\n      var chart = new google.visualization.ComboChart(document.getElementById(\'chart_div\'));\n\n        const options = {\n          title: \'Business Growth Model (Retention-Driven)\',\n          height: 500,\n          legend: { position: \'top\' },\n          seriesType: \'bars\',\n          series: {\n            0: { type: \'bars\', targetAxisIndex: 0 }, // New Clients\n            1: { type: \'bars\', targetAxisIndex: 0 }, // Churned Clients\n            2: { type: \'line\', targetAxisIndex: 0 }, // Active Clients\n            3: { type: \'line\', targetAxisIndex: 1 }, // Revenue\n            4: { type: \'line\', targetAxisIndex: 1 }  // ROAS\n          },\n          vAxes: {\n            0: {\n              title: \'Clients\',\n              viewWindow: { min: -10 }\n            },\n            1: {\n              title: \'Revenue / ROAS\',\n              format: \'short\'\n            }\n          },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true }\n        };\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n            document.getElementById(\'dashboard_div\'));\n\n        // Create a range slider, passing some options\n        var donutRangeSlider = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter_div\',\n          \'options\': {\n            \'filterColumnLabel\': \'Time\"\n          }\n        });\n        // Establish dependencies, declaring that \'filter\' drives \'pieChart\',\n        // so that the pie chart will only display entries that are let through\n        // given the chosen slider range.\n        dashboard.bind(donutRangeSlider, chart);\n\nchart.draw(data, options);\n    }\n</script>\n<!-- /wp:html -->','Pricing','','inherit','closed','closed','','452-revision-v1','','','2026-01-08 07:04:32','2026-01-08 07:04:32','',452,'https://happytailspawcare.com/?p=500',0,'revision','',0),
(503,1,'2026-01-08 20:04:00','2026-01-08 20:04:00','<!-- wp:paragraph -->\n<p>if chart type is a ui control widget  dropdown box, it can have a wordpress conditional redirect from forminator filling in these variations..</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>use visualization dashboard <a href=\"https://developers.google.com/chart/interactive/docs/gallery/controls\">https://developers.google.com/chart/interactive/docs/gallery/controls</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n    <!--Div that will hold the dashboard-->\n    <div id=\"dashboard_div\">\n      <!--Divs that will hold each control and chart-->\n      <div id=\"filter_div\"></div>\n      <div id=\"chart_div\" style=\"width:100%; height:500px;\"></div>\n    </div>\n<script type=\"text/javascript\" src=\"https://www.gstatic.com/charts/loader.js\"></script>\n\n<script>\n  //fetcg Xhr\nfunction getData(url) {\n  try {\n    const response = fetch(url, { method: \'GET\' });\n\n    if (!response.ok) {\n      throw new Error(`HTTP error! status: ${response.status}`);\n    }\n\n    const responseData =  response.json();\n    console.log(\'Success:\', responseData);\n  } catch (error) {\n    console.error(\'Error posting data:\', error);\n  }\n}\n<!--\n  window.onload = function() {\n\ngetData(\"https://script.google.com/macros/s/AKfycbw4zHkAUbRLoSHmkYuleuOAUr6o9hMzl7ule6A6IEnEytsxfMUCQG3tFNcSqVfGHUwr/exec?action=update\");\n\n};-->\n</script>\n\n<script>\ngoogle.charts.load(\'current\',{\'packages\':[\'corechart\',\'controls\']});\ngoogle.charts.setOnLoadCallback(chartStuff);\nfunction chartStuff() {\n        var dataSourceUrl = \n        \"https://script.google.com/macros/s/AKfycbw4zHkAUbRLoSHmkYuleuOAUr6o9hMzl7ule6A6IEnEytsxfMUCQG3tFNcSqVfGHUwr/exec?action=update\";\n        var query = new google.visualization.Query(dataSourceUrl);\n        query.setTimeout(1);\n        query.send(qr);\n}\n\nfunction qr(response) {\n  drawChart();\n      if (response.isError()) {\n        console.