(526,1,'2026-01-09 23:44:52','2026-01-09 23:44:52','<!-- wp:paragraph -->\n<p>if chart type is a ui control widget  dropdown box, it can have a wordpress conditional redirect from forminator filling in these variations..</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>use visualization dashboard <a href=\"https://developers.google.com/chart/interactive/docs/gallery/controls\">https://developers.google.com/chart/interactive/docs/gallery/controls</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n    <!--Div that will hold the dashboard-->\n    <div id=\"dashboard_div\">\n      <!--Divs that will hold each control and chart-->\n      <div id=\"toolbar_div\"></div>\n      <div id=\"filter_div\"></div>\n      <div id=\"chart_div\" style=\"width:100%; height:500px;\"></div>\n      <div id=\"b1\"></div>\n    </div>\n<script type=\"text/javascript\" src=\"https://www.gstatic.com/charts/loader.js\"></script>\n\n<script>\n\n  google.charts.load(\'current\',{\'packages\':[\'corechart\',\'controls\']});\n  google.charts.setOnLoadCallback(chartStuff);\n\nfunction chartStuff() {\n  console.log(\"chartStuff begin\")\n  var dataSourceUrl = \"https://script.google.com/macros/s/AKfycbw4zHkAUbRLoSHmkYuleuOAUr6o9hMzl7ule6A6IEnEytsxfMUCQG3tFNcSqVfGHUwr/exec?action=update\";\n\n  //  kludge here\n  //\n  var query = new google.visualization.Query(dataSourceUrl);\n  console.log(\"qr send\")\n  query.setTimeout(1);\n  query.send(qr);\n  console.log(\"chartStuff exit\")\n}\n\n//\nfunction qr(response) {\n  console.log(\"qr begin\")\n  drawChart();\n  console.log(\"CORS bypass workaround, this call should fail!\")\n}\n\n function init() {\n    var options = {\n      width: 400,\n      height: 240,\n      animation:{\n        duration: 1000,\n        easing: \'out\',\n      },\n      vAxis: {minValue:0, maxValue:1000}\n    };\n    var data = new google.visualization.DataTable();\n    data.addColumn(\'string\', \'N\');\n    data.addColumn(\'number\', \'Value\');\n    data.addRow([\'V\', 200]);\n\n    var chart = new google.visualization.ColumnChart(\n        document.getElementById(\'visualization\'));\n    var button = document.getElementById(\'b1\');\n\n    function drawAChart() {\n      // Disabling the button while the chart is drawing.\n      button.disabled = true;\n      google.visualization.events.addListener(chart, \'ready\',\n          function() { button.disabled = false; });\n      chart.draw(data, options);\n    }\n\n    button.onclick = function() {\n      var newValue = 1000 - data.getValue(0, 1);\n      data.setValue(0, 1, newValue);\n      drawAChart();\n    }\n    drawAChart();\n  }\n\nfunction drawToolbar() {\n  var components = [\n      {type: \'igoogle\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\',\n       gadget: \'https://www.google.com/ig/modules/pie-chart.xml\',\n       userprefs: {\'3d\': 1}},\n      {type: \'html\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\'},\n      {type: \'csv\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\'},\n      {type: \'htmlcode\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\',\n       gadget: \'https://www.google.com/ig/modules/pie-chart.xml\'}\n  ];\n\n  var container = document.getElementById(\'toolbar_div\');\n  google.visualization.drawToolbar(container, components);\n};\n\nfunction drawChart() {\n       console.log(\"drawChart begin\")\n       var dataSourceUrl = \'https://docs.google.com/spreadsheets/d/1YYVl5EGOy2WOk74l3DmtaugP5RgW_c6UQDtJkTE4itE/gviz/tq?gid=433166320&headers=1&tq=\';\n\n     // var chart = new google.visualization.ComboChart(document.getElementById(\'chart_div\'));\n\n      var chart = new google.visualization.ChartWrapper({\n        \'charType\': \'ComboChart\',\n        \'containerId\': \'chart_div\',\n        \'options\': {\n          title: \'Business Growth Model (Retention-Driven)\',\n          height: 500,\n          legend: { position: \'top\' },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true }\n        }\n        });\n       console.log(\"setDataSource\")\n       chart.setDataSourceUrl(dataSourceUrl);\n\n       console.log(\" post setDataSource\")\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n            document.getElementById(\'dashboard_div\'));\n       console.log(\" post setDataSource\")\n\n       console.log(\"new range slider\")\n        // Create a range slider, passing some options\n        var rangeSlider = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter_div\',\n          \'options\': { \'filterColumnLabel\': \"\" }\n        });\n        // Establish dependencies, declaring that \'filter\' drives \'pieChart\',\n        // so that the pie chart will only display entries that are let through\n        // given the chosen slider range.\n       console.log(\"bind\")\n        dashboard.bind(rangeSlider, chart);\n       console.log(\"draw\")\n        dashboard.draw();\n       console.log(\"drawChart exit\")\n    }\n</script>\n\n<!-- /wp:html -->','Pricing','','inherit','closed','closed','','452-revision-v1','','','2026-01-09 23:44:52','2026-01-09 23:44:52','',452,'https://happytailspawcare.com/?p=526',0,'revision','',0),
