({\n            chartType: \'LineChart\',\n            options: {\'title\': \'blargh\'},\n            containerId: \'chart_div\'\n          });\n*/\n\n  //https://stackoverflow.com/questions/46613501/how-to-add-a-style-role-column-to-a-google-charts-aggregated-datatable\n      var dataView = new google.visualization.DataView(data);\n  dataView.setColumns([3,4 {\n    role: \'tooltip\',\n      type: \'number\'\n  })\n\n\n      var chart = new google.visualization.ChartWrapper({\n        \'chartType\': \'ComboChart\',\n        \'containerId\': \'chart_div\',\n        \'options\': {\n          title: \'Business Growth Model (Retention-Driven)\',\n          height: 500,\n          legend: { position: \'top\' },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true },\n          \n          seriesType: \'bars\',\n\n          series: {\n            0: { type: \'bars\', targetAxisIndex: 0 }, // New Clients\n            1: { type: \'bars\', targetAxisIndex: 0 }, // Churned Clients\n            2: { type: \'line\', targetAxisIndex: 0 }, // Active Clients\n            3: { type: \'line\', targetAxisIndex: 1 }, // Revenue\n            4: { type: \'line\', targetAxisIndex: 1 }  // Ad_Spend\n          },\n\n          vAxes: {\n            0: {\n              title: \'Clients\',\n              viewWindow: { min: -10 }\n            },\n            1: {\n              title: \'Revenue / Ad Spend\',\n              format: \'short\'\n            }\n          },\n        }\n        });\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n            document.getElementById(\'dashboard_div\'));\n\n       console.log(\" post setDataSource\")\n\n       console.log(\"new range slider\")\n        // Create a range slider, passing some options\n        var rangeSlider = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter_div\',\n          \'options\': { \'filterColumnLabel\': \"ad_spend\" }\n        });\n\n        \n  // save reference to dashboard\n       console.log(\"constructor dashboard.bind\")\n  var dashboard = new google.visualization.Dashboard(document.getElementById(\'dashboard_div\')).bind(rangeSlider, chart);\n       console.log(\"draw\")\n//  dashboard.draw(data);\n  dashboard.draw(dataView);\n\n  // include within drawDashboard\n  $(window).resize(function() {\n       console.log(\"resize\")\n    // reference dashboard instance\n    dashboard.draw(dataView);\n  });\n\n        // Establish dependencies, declaring that \'filter\' drives \'pieChart\',\n        // so that the pie chart will only display entries that are let through\n        // given the chosen slider range.\n//        dashboard.bind(rangeSlider, chart);\n       console.log(\"drawChart exit\")\n    }\n</script>\n\n<!-- /wp:html -->','Pricing','','inherit','closed','closed','','452-revision-v1','','','2026-01-10 06:40:10','2026-01-10 06:40:10','',452,'https://happytailspawcare.com/?p=542',0,'revision','',0),
