art\n        var  wrapper = new google.visualization.ChartWrapper({\n            chartType: \'LineChart\',\n            options: {\'title\': \'blargh\'},\n            containerId: \'chart_div\'\n          });\n*/\n\n  //https://stackoverflow.com/questions/46613501/how-to-add-a-style-role-column-to-a-google-charts-aggregated-datatable\n  /*\n      var dataView = new google.visualization.DataView(data);\n  dataView.setColumns([3,4, {\n    role: \'tooltip\',\n      type: \'string\'\n  }])\n*/\n\n\n      var chart = new google.visualization.ChartWrapper({\n        \'chartType\': \'ComboChart\',\n        \'containerId\': \'chart_div\',\n        \'options\': {\n          title: \'Business Growth Model (Retention-Driven)\',\n          crosshair: { trigger: \'both\' },\n          height: 750,\n          legend: {\n               position: \'bottom\',\n            orientation: \'vertical\',\n            textStyle: {\n              color: \'#ff0000\',\n              fontSize: 14\n            }\n          },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true },\n          \n          seriesType: \'bars\',\n\n          series: {\n            0: { type: \'bars\', targetAxisIndex: 0 }, // New Clients\n            1: { type: \'bars\', targetAxisIndex: 0 }, // Churned Clients\n            2: { type: \'line\', targetAxisIndex: 0 }, // Active Clients\n            3: { type: \'line\', targetAxisIndex: 1 }, // Revenue\n            4: { type: \'line\', targetAxisIndex: 1 }  // Ad_Spend\n          },\n\n          vAxes: {\n            0: {\n              title: \'Clients\',\nformat:\'short\'\n            },\n            1: {\n              title: \'Revenue / Ad Spend\',\n              format: \'short\'\n            }\n          },\n        }\n        });\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n            document.getElementById(\'dashboard_div\'));\n\n       console.log(\" post setDataSource\")\n\n       console.log(\"new range slider\")\n        // Create a range slider, passing some options\n        var rangeSlider = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter_div\',\n          \'options\': { \'filterColumnLabel\': \"ad_spend\" }\n        });\n\n        var rangeSlider2 = new google.visualization.ControlWrapper({\n          \'controlType\': \'CategoryFilter\',\n          \'containerId\': \'filter2_div\',\n          \'options\': { \n                \'ui\': {\n                  \'allowMultiple\': \"false\"\n                },\n                \'filterColumnLabel\': \"new_leads\",\n                \'values\': [\'10\',\'20\',\'30\',\'40\'],\n          }\n        });\n\n        var rangeSlider3 = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter3_div\',\n          \'options\': { \'filterColumnLabel\': \"client_retention_rate\" }\n        });\n\n        \n  drawToolbar();\n\n//slider range func            programmaticSlider.setState({\'lowValue\': 2, \'highValue\': 5}); \n  // save reference to dashboard\n       console.log(\"constructor dashboard.bind\")\n  var dashboard = new google.visualization.Dashboard(document.getElementById(\'dashboard_div\'))\n    dashboard.bind(rangeSlider, chart);\n    dashboard.bind(rangeSlider2, chart);\n    dashboard.bind(rangeSlider3, chart);\n       console.log(\"draw\")\n  dashboard.draw(data);\n//  dashboard.draw(dataView);\n       console.log(\"resize\")\n/*\n  // include within drawDashboard\n  $(window).resize(function() {\n       console.log(\"resize\")\n    // reference dashboard instance\n    dashboard.draw(dataView);\n  });\n*/\n        // Establish dependencies, declaring that \'filter\' drives \'pieChart\',\n        // so that the pie chart will only display entries that are let through\n        // given the chosen slider range.\n//        dashboard.bind(rangeSlider, chart);\n       console.log(\"drawChart exit\")\n    }\n</script>\n\n<!-- /wp:html --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://developers.google.com/chart/interactive/docs/gallery/controls\">https://developers.google.com/chart/interactive/docs/gallery/controls</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Pricing','','inherit','closed','closed','','452-revision-v1','','','2026-01-16 04:25:06','2026-01-16 04:25:06','',452,'https://happytailspawcare.com/?p=574',0,'revision','',0),
