(603,1,'2026-01-19 19:22:27','2026-01-19 19:22:27','<!-- wp:uagb/container {\"block_id\":\"0250348c\",\"directionDesktop\":\"row\",\"variationSelected\":true,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-0250348c alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"43f50ac4\",\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-43f50ac4\"><!-- wp:html -->\n<!--Div that will hold the dashboard-->\n    <div id=\"dashboard_div\">\n      <!--Divs that will hold each control and chart-->\n      <div id=\"toolbar_div\"></div>\n      <div id=\"filter_div\"></div>\n      <div id=\"filter2_div\"></div>\n      <div id=\"filter3_div\"></div>\n      <div id=\"chart_div\" style=\"width:100%; height:100%;\"></div>\n      <div id=\"b1\"></div>\n    </div>\n<script type=\"text/javascript\" src=\"https://www.gstatic.com/charts/loader.js\"></script>\n\n<script>\n\n  google.charts.load(\'current\',{\'packages\':[\'corechart\',\'controls\', \'charteditor\']});\n  google.charts.setOnLoadCallback(chartStuff);\n\nfunction chartStuff() {\n  console.log(\"chartStuff begin\")\n  var dataSourceUrl = \"https://script.google.com/macros/s/AKfycbw4zHkAUbRLoSHmkYuleuOAUr6o9hMzl7ule6A6IEnEytsxfMUCQG3tFNcSqVfGHUwr/exec?action=update\";\n\n  //  kludge here\n  //\n  var query = new google.visualization.Query(dataSourceUrl);\n  console.log(\"CORS bypass workaround, this call should fail!\")\n  query.setTimeout(1);\n  query.send(queryResponseWebAppScript);\n}\n\n//\nfunction queryResponseWebAppScript(response) {\n  console.log(\"queryResponseWebAppScript begin\")\n\n  var dataSourceUrl = \'https://docs.google.com/spreadsheets/d/1YYVl5EGOy2WOk74l3DmtaugP5RgW_c6UQDtJkTE4itE/gviz/tq?gid=433166320&headers=1&tq=\';\n\n  var query = new google.visualization.Query(dataSourceUrl);\n  query.send(drawChart);\n}\n\n  //animation\n function init() {\n    var options = {\n      width: 400,\n      height: 240,\n      animation:{\n        duration: 1000,\n        easing: \'out\',\n      },\n      vAxis: {minValue:0, maxValue:1000}\n    };\n    var data = new google.visualization.DataTable();\n    data.addColumn(\'string\', \'N\');\n    data.addColumn(\'number\', \'Value\');\n    data.addRow([\'V\', 200]);\n\n    var chart = new google.visualization.ColumnChart(\n        document.getElementById(\'visualization\'));\n    var button = document.getElementById(\'b1\');\n\n    function drawAChart() {\n      // Disabling the button while the chart is drawing.\n      button.disabled = true;\n      google.visualization.events.addListener(chart, \'ready\',\n          function() { button.disabled = false; });\n      chart.draw(data, options);\n    }\n\n    button.onclick = function() {\n      var newValue = 1000 - data.getValue(0, 1);\n      data.setValue(0, 1, newValue);\n      drawAChart();\n    }\n    drawAChart();\n  }\n\n  //export / downloads\nfunction drawToolbar() {\n  var components = [\n    {type: \'metadata\', datasource: \'https://docs.google.com/spreadsheets/d/1YYVl5EGOy2WOk74l3DmtaugP5RgW_c6UQDtJkTE4itE/edit?gid=454960513#gid=454960513\'},\n      {type: \'sheetdata\', datasource: \'https://docs.google.com/spreadsheets/d/1YYVl5EGOy2WOk74l3DmtaugP5RgW_c6UQDtJkTE4itE/gviz/tq?gid=433166320&headers=1&tq=\'\'},\n      {type: \'csv\', datasource: \'https://docs.google.com/spreadsheets/d/1YYVl5EGOy2WOk74l3DmtaugP5RgW_c6UQDtJkTE4itE/gviz/tq?gid=433166320&headers=1&tq=\'\'},\n      \n  ];\n\n  var container = document.getElementById(\'toolbar_div\');\n  google.visualization.drawToolbar(container, components);\n};\n\nfunction drawChart(response) {\n       console.log(\"drawChart begin\")\n       var data = response.getDataTable();\n\n     // var chart = new google.visualization.ComboChart(document.getElementById(\'chart_div\'));\n\n  /*\n          // Draw a column chart\n        var  wrapper = new google.visualization.ChartWrapper({\n            chartType: \'LineChart\',\n            options: {\'title\': \'blargh\'},\n            containerId: \'chart_div\'\n          });\n*/\n\n  //https://stackoverflow.com/questions/46613501/how-to-add-a-style-role-column-to-a-google-charts-aggregated-datatable\n  /*\n      var dataView = new google.visualization.DataView(data);\n  dataView.setColumns([3,4, {\n    role: \'tooltip\',\n      type: \'string\'\n  }])\n*/\n\n      var view = new google.visualization.DataView(data);\n//  view.hideColumns([5,6]);\n  /*\n  view.setRows(data.getFilteredRows([{\n    column: 0,\n    minValue: data.getColumnRange(0).max\n  }]));\n*/\n      var chart = new google.visualization.ChartWrapper({\n        \'chartType\': \'ComboChart\',\n        \'containerId\': \'chart_div\',\n        \'options\': {\n          title: \'Business Growth Model (Retention-Driven)\',\n          crosshair: { trigger: \'both\' },\n          height: 750,\n          legend: {\n               position: \'bottom\',\n            orientation: \'vertical\',\n            textStyle: {\n              color: \'#ff0000\',\n              fontSize: 14\n            }\n          },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true },\n          \n          seriesType: \'bars\',\n\n          series: {\n            0: { type: \'bars\', targetAxisIndex: 0 }, // New Clients\n            1: { type: \'line\', targetAxisIndex: 0 }, // Active Clients\n            2: { type: \'bars\', targetAxisIndex: 0 }, // Churned Clients\n            3: { type: \'line\', targetAxisIndex: 1 }, // Revenue\n            4: { type: \'line\', targetAxisIndex: 1 }  // Ad_Spend\n          },\n\n          vAxes: {\n            0: {\n              title: \'Clients\',\nformat:\'short\'\n            },\n            1: {\n              title: \'Revenue / Ad Spend\',\n              format: \'short\'\n            }\n          },\n        }\n        });\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n        