n      width: 400,\n      height: 240,\n      animation:{\n        duration: 1000,\n        easing: \'out\',\n      },\n      vAxis: {minValue:0, maxValue:1000}\n    };\n    var data = new google.visualization.DataTable();\n    data.addColumn(\'string\', \'N\');\n    data.addColumn(\'number\', \'Value\');\n    data.addRow([\'V\', 200]);\n\n    var chart = new google.visualization.ColumnChart(\n        document.getElementById(\'visualization\'));\n    var button = document.getElementById(\'b1\');\n\n    function drawAChart() {\n      // Disabling the button while the chart is drawing.\n      button.disabled = true;\n      google.visualization.events.addListener(chart, \'ready\',\n          function() { button.disabled = false; });\n      chart.draw(data, options);\n    }\n\n    button.onclick = function() {\n      var newValue = 1000 - data.getValue(0, 1);\n      data.setValue(0, 1, newValue);\n      drawAChart();\n    }\n    drawAChart();\n  }\n\n  //export / downloads\nfunction drawToolbar() {\n  var components = [\n      {type: \'igoogle\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\',\n       gadget: \'https://www.google.com/ig/modules/pie-chart.xml\',\n       userprefs: {\'3d\': 1}},\n      {type: \'html\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\'},\n      {type: \'csv\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\'},\n      {type: \'htmlcode\', datasource: \'https://spreadsheets.google.com/tq?key=pCQbetd-CptHnwJEfo8tALA\',\n       gadget: \'https://www.google.com/ig/modules/pie-chart.xml\'}\n  ];\n\n  var container = document.getElementById(\'toolbar_div\');\n  google.visualization.drawToolbar(container, components);\n};\n\nfunction drawChart(response) {\n       console.log(\"drawChart begin\")\n       var data = response.getDataTable();\nconsole.log(data);\n\n     // var chart = new google.visualization.ComboChart(document.getElementById(\'chart_div\'));\n\n  /*\n          // Draw a column chart\n        var  wrapper = new google.visualization.ChartWrapper({\n            chartType: \'LineChart\',\n            options: {\'title\': \'blargh\'},\n            containerId: \'chart_div\'\n          });\n*/\n\n  //https://stackoverflow.com/questions/46613501/how-to-add-a-style-role-column-to-a-google-charts-aggregated-datatable\n  /*\n      var dataView = new google.visualization.DataView(data);\n  dataView.setColumns([3,4, {\n    role: \'tooltip\',\n      type: \'string\'\n  }])\n*/\n\n      var view = new google.visualization.DataView(data);\n//  view.hideColumns([5,6]);\n  /*\n  view.setRows(data.getFilteredRows([{\n    column: 0,\n    minValue: data.getColumnRange(0).max\n  }]));\n*/\n      var chart = new google.visualization.ChartWrapper({\n        \'chartType\': \'ComboChart\',\n        \'containerId\': \'chart_div\',\n        \'options\': {\n          title: \'Business Growth Model (Retention-Driven)\',\n          crosshair: { trigger: \'both\' },\n          height: 750,\n          legend: {\n               position: \'bottom\',\n            orientation: \'vertical\',\n            textStyle: {\n              color: \'#ff0000\',\n              fontSize: 14\n            }\n          },\n          focusTarget: \'category\',\n          tooltip: { isHtml: true },\n          \n          seriesType: \'bars\',\n\n          series: {\n            0: { type: \'bars\', targetAxisIndex: 0 }, // New Clients\n            1: { type: \'line\', targetAxisIndex: 0 }, // Active Clients\n            2: { type: \'bars\', targetAxisIndex: 0 }, // Churned Clients\n            3: { type: \'line\', targetAxisIndex: 1 }, // Revenue\n            4: { type: \'line\', targetAxisIndex: 1 }  // Ad_Spend\n          },\n\n          vAxes: {\n            0: {\n              title: \'Clients\',\nformat:\'short\'\n            },\n            1: {\n              title: \'Revenue / Ad Spend\',\n              format: \'short\'\n            }\n          },\n        }\n        });\n \n        // Create a dashboard.\n        var dashboard = new google.visualization.Dashboard(\n            document.getElementById(\'dashboard_div\'));\n\n       console.log(\" post setDataSource\")\n\n       console.log(\"new range slider\")\n        // Create a range slider, passing some options\n        var rangeSlider = new google.visualization.ControlWrapper({\n          \'controlType\': \'NumberRangeFilter\',\n          \'containerId\': \'filter_div\',\n          \'options\': { \'filterColumnLabel\': \"Ad Spend\" }\n        });\n\n  drawToolbar();\n\n//slider range func            programmaticSlider.setState({\'lowValue\': 2, \'highValue\': 5}); \n  // save reference to dashboard\n       console.log(\"constructor dashboard.bind\")\n  var dashboard = new google.visualization.Dashboard(document.getElementById(\'dashboard_div\'))\n       console.log(\"draw\")\ndashboard.bind(rangeSlider, chart);\n  dashboard.draw(view);\n//  dashboard.draw(dataView);\n       console.log(\"resize\")\n/*\n  // include within drawDashboard\n  $(window).resize(function() {\n       console.log(\"resize\")\n    // reference dashboard instance\n    dashboard.draw(dataView);\n  });\n*/\n        // Establish dependencies, declaring that \'filter\' drives \'pieChart\',\n        // so that the pie chart will only display entries that are let through\n        // given the chosen slider range.\n        \n       console.log(\"drawChart exit\")\n    }\n</script>\n\n\n<!-- /wp:html --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://developers.google.com/chart/interactive/docs/gallery/controls\">https://developers.google.com/chart/interactive/docs/gallery/controls</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Pricing','','inherit','closed','closed','','452-revision-v1','','','2026-01-19 20:47:10','2026-01-19 20:47:10','',452,'https://happytailspawcare.com/?p=626',0,'revision','',0),
