1 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\" style=\"letter-spacing:-1px\"><mark style=\"background-color:rgba(0, 0, 0, 0);color:#248eaf\" class=\"has-inline-color\">We Fetch the Clients </mark><mark style=\"background-color:rgba(0, 0, 0, 0);color:#1e2a38\" class=\"has-inline-color\">You Handle the Pets</mark></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"SWTHideDesktop\":true} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"100%\",\"className\":\"fixed-scrollby-image fixed\",\"SWTHideDesktop\":true} -->\n<div style=\"height:100%\" aria-hidden=\"true\" id=\"kewl-hero-picture\" class=\"wp-block-spacer fixed-scrollby-image fixed\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {\"height\":\"360px\",\"SWTHideDesktop\":true} -->\n<div style=\"height:360px\" aria-hidden=\"true\" id=\"fixed-spacer-hero-helper\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|xx-large\",\"bottom\":\"var:preset|spacing|xx-large\"},\"blockGap\":\"var:preset|spacing|x-large\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-tertiary-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--xx-large);padding-bottom:var(--wp--preset--spacing--xx-large)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:uagb/image {\"block_id\":\"725c75ec\",\"url\":\"https://happytailspawcare.com/wp-content/uploads/2025/10/dogs_conference_room_laptop_mobile_2.png\",\"urlTablet\":\"https://happytailspawcare.com/wp-content/uploads/2025/10/dogs_conference_room_laptop_mobile_2.png\",\"urlMobile\":\"https://happytailspawcare.com/wp-co